// Verifica a assinatura HMAC-SHA256 do header X-N8N-Signature (spec 035, CA-03).
// A FastSocial API assina com: createHmac('sha256', N8N_WEBHOOK_SECRET).update(JSON.stringify({ contentPieceId, workspaceId })).digest('hex')
// (ver content-pieces.service.ts#notifyApproved) — a ordem das chaves no
// objeto reconstruído aqui TEM que bater exatamente com a ordem lá
// (contentPieceId primeiro, workspaceId depois), senão a assinatura nunca
// confere mesmo com o segredo certo.
//
// PRÉ-REQUISITO deste node: a instância do n8n precisa permitir acesso a
// variáveis de ambiente dentro de Code nodes (N8N_BLOCK_ENV_ACCESS_IN_NODE
// não pode estar habilitado para N8N_WEBHOOK_SECRET). Como este n8n é
// compartilhado com outros workflows da agência (spec 032), isso não pôde
// ser confirmado neste spec sem acesso à configuração de ambiente do
// container — validar antes de ativar este workflow em produção.
const crypto = require('crypto');

const body = $input.item.json.body ?? {};
const headers = $input.item.json.headers ?? {};
const receivedSignature = headers['x-n8n-signature'] ?? '';
const secret = $env.N8N_WEBHOOK_SECRET ?? '';

const payload = JSON.stringify({ contentPieceId: body.contentPieceId, workspaceId: body.workspaceId });
const expectedSignature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

const valid = !!secret && receivedSignature === expectedSignature;

return [{ json: { valid, contentPieceId: body.contentPieceId, workspaceId: body.workspaceId } }];

// Calcula o próximo horário dentro de preferredTimes (ex: ["09:00","18:00"])
// com espaçamento mínimo de 30 minutos em relação a qualquer publicação já
// agendada para o workspace (CA-02) — em vez de só repetir cegamente o
// mesmo preferred_time toda vez que uma peça é aprovada.
const MIN_SPACING_MINUTES = 30;
const SEARCH_DAYS_AHEAD = 30;

const preferredTimes = $('Buscar Config do Pipeline').item.json.preferredTimes ?? ['09:00', '18:00'];
const upcoming = $('Buscar Agendamentos Futuros').all().map(i => new Date(i.json.scheduledAt).getTime());
const accounts = $('Buscar Contas Sociais').all().map(i => i.json).filter(a => a.status === 'connected');

// Seleção do MVP: primeira conta conectada do workspace. Melhoria futura
// (mesmo racional documentado no spec 034 para escolha de template):
// escolher por rede/desempenho em vez de pegar a primeira.
const socialAccountId = accounts.length > 0 ? accounts[0].id : null;

function collides(candidateMs) {
  return upcoming.some(t => Math.abs(t - candidateMs) < MIN_SPACING_MINUTES * 60 * 1000);
}

const now = Date.now();
let chosen = null;
for (let dayOffset = 0; dayOffset < SEARCH_DAYS_AHEAD && !chosen; dayOffset++) {
  for (const time of preferredTimes) {
    const [h, m] = time.split(':').map(Number);
    const candidate = new Date();
    candidate.setDate(candidate.getDate() + dayOffset);
    candidate.setHours(h, m, 0, 0);
    const candidateMs = candidate.getTime();
    if (candidateMs <= now) continue;
    if (collides(candidateMs)) continue;
    chosen = candidate;
    break;
  }
}

if (!chosen) {
  throw new Error('Não foi possível achar um horário livre nos próximos ' + SEARCH_DAYS_AHEAD + ' dias — agenda do workspace está saturada.');
}

return [{
  json: {
    workspaceId: $('Validar Assinatura HMAC').item.json.workspaceId,
    contentPieceId: $('Validar Assinatura HMAC').item.json.contentPieceId,
    socialAccountId,
    scheduledAt: chosen.toISOString(),
  },
}];
